window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"YBPHvu1PVAc","speaker":"Javier Gerardo Milei","role":"President","country":"Argentina","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=YBPHvu1PVAc","date":"20260923","title":"🇦🇷 Argentina - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1213,"words":3084,"counts":{"claims":31,"promises":4,"attacks":10},"topics":[{"topic":"Artificial intelligence","share":0.2641,"seconds":320},{"topic":"Falkland Islands","share":0.2089,"seconds":253},{"topic":"UN reform","share":0.1803,"seconds":219},{"topic":"Argentina economy","share":0.1023,"seconds":124},{"topic":"Argentina reconstruction","share":0.0853,"seconds":103},{"topic":"Iran Israel","share":0.0542,"seconds":66},{"topic":"Industrial revolution","share":0.0535,"seconds":65},{"topic":"WHO pandemic","share":0.0515,"seconds":62}],"timeline":[[3,64,"Argentina economy"],[65,129,"UN reform"],[130,209,"UN reform"],[209,271,"Falkland Islands"],[272,333,"Falkland Islands"],[334,402,"Falkland Islands"],[404,466,"Falkland Islands"],[467,533,"Iran Israel"],[535,611,"UN reform"],[612,674,"WHO pandemic"],[676,736,"Artificial intelligence"],[737,802,"Industrial revolution"],[803,876,"Artificial intelligence"],[878,941,"Artificial intelligence"],[941,1003,"Artificial intelligence"],[1005,1067,"Artificial intelligence"],[1068,1131,"Argentina economy"],[1133,1193,"Argentina reconstruction"],[1194,1237,"Argentina reconstruction"]],"stances":{"Argentina economy":"Javier Gerardo Milei states that upon taking office, his administration faced a country in ruins and the worst crisis in its history, committing to confront these problems with absolute honesty.","UN reform":"Javier Gerardo Milei argues that the UN must confront uncomfortable truths regarding its failures and address new challenges like artificial intelligence.","Falkland Islands":"Javier Gerardo Milei asserts that the Malvinas are a national cause and that British oil extraction activities on the Argentine continental shelf are illegal.","Iran Israel":"Milei states that Argentina has aligned with the West and Israel, condemning Iranian attacks on Israel and designating the Iranian Revolutionary Guard as a terrorist organization.","WHO pandemic":"Javier Gerardo Milei argues that the World Health Organization and UN bodies prioritized social control over scientific evidence during the pandemic, causing millions of deaths and economic ruin, which led Argentina to withdraw from the organization.","Artificial intelligence":"Javier Gerardo Milei argues that artificial intelligence is being used as a tool to instill psychological terror in the public, similar to how governments have historically used emergencies to expand their power.","Industrial revolution":"Javier Gerardo Milei argues that technological advances during the industrial revolution did not cause mass unemployment as pessimists predicted, but instead expanded human capabilities.","Argentina reconstruction":"Javier Gerardo Milei asserts that Argentina is a land of abundant resources and talent that has historically welcomed immigrants to build prosperity, and he declares the nation's desire to be free, prosperous, sovereign, and great again."},"claims":[{"t":48,"quote":"Today I address you for the third time as president of all Argentines.","topic":"Argentina economy","kind":"fact"},{"t":52,"quote":"When we took office of a country in ruins, on the brink of the worst crisis in its history","topic":"Argentina economy","kind":"fact"},{"t":105,"quote":"78 years ago, this house declared that all human beings are born free and equal in dignity and rights.","topic":"UN reform","kind":"fact"},{"t":180,"quote":"They have systematically voted against Israel while remaining silent in the face of Islamic terrorism and the genocide of Christians in Africa.","topic":"UN reform","kind":"fact"},{"t":191,"quote":"an organization established to defend the territorial sovereignty of its members decided to look the other way with regard to the situation of the Malvvenas Islands, South Georgia Islands at South Sandwich Islands and the surrounding maritime","topic":"UN reform","kind":"fact"},{"t":224,"quote":"50 years ago, this very assembly adopted resolution 3149 which calls on parties to refrain from introducing unilateral modifications while the dispute remains unresolved.","topic":"Falkland Islands","kind":"fact"},{"t":242,"quote":"Today, the Sea Lion project is moving towards oil extraction on the Argentine continental shelf in the North Malvinus basin under British licenses that Argentina rejects as illegal and illegitimate.","topic":"Falkland Islands","kind":"fact"},{"t":272,"quote":"That is why I wish to ask a question. What use is a resolution if for decades the other party can act in direct contravention of it while that resolution remains intact in the archives but powerless in the face of reality.","topic":"Falkland Islands","kind":"fact"},{"t":334,"quote":"We've availed ourselves of the legal remedies at our disposal. We've imposed sanctions on the companies involved and their suppliers. And we've submitted a national sovereignty defense bill to Congress.","topic":"Falkland Islands","kind":"fact"},{"t":370,"quote":"the principle of self-determination does not apply in this case since the population was implanted by the occupying power on a territory whose sovereignty is in dispute.","topic":"Falkland Islands","kind":"fact"},{"t":404,"quote":"Once again, we call on the United Kingdom to resume negotiations with a view to finding a peaceful solution to the sovereignty dispute as required by international law.","topic":"Falkland Islands","kind":"fact"},{"t":416,"quote":"We also reiterate our invitation to proceed without delay to an exchange of views with a view to resolving the issue concerning the affforementioned dispute over the exploitation of our natural resources.","topic":"Falkland Islands","kind":"fact"},{"t":527,"quote":"continue to seek justice for the two terrorist attacks perpetrated on Argentine soil in 1992 and 1994","topic":"Iran Israel","kind":"fact"},{"t":566,"quote":"they have built a bureaucratic leviathan devoted to deciding how the peoples of the world and their citizens should live","topic":"UN reform","kind":"fact"},{"t":589,"quote":"We saw this with the millennium agenda. We saw it with the 2030 agenda with economic regulation, gender agendas, environmental extremism, and unchecked","topic":"UN reform","kind":"fact"},{"t":632,"quote":"ruined jobs that ruined the education of entire generation of children and cost the lives of millions of people who died alone without basic medical care","topic":"WHO pandemic","kind":"fact"},{"t":666,"quote":"Argentina which boasted of being the World Health Organization's star pupil","topic":"WHO pandemic","kind":"fact"},{"t":719,"quote":"The printing press, the steam engine, electricity, the internet, every great technological revolution has been accompanied by fears about what it would destroy, particularly jobs.","topic":"Artificial intelligence","kind":"fact"},{"t":741,"quote":"When it began, the world was home to some 800 million human beings.","topic":"Industrial revolution","kind":"number"},{"t":755,"quote":"given that the world's population has since increased more than 10fold the global employment rate today would be at That is absurd.","topic":"Industrial revolution","kind":"fact"},{"t":807,"quote":"Artificial intelligence or super intelligence as Donald Trump said can double our productivity uh in a way that we do not yet comprehend.","topic":"Artificial intelligence","kind":"fact"},{"t":818,"quote":"Artificial intelligence will be the pin factory of the 21st century and much more besides.","topic":"Artificial intelligence","kind":"fact"},{"t":926,"quote":"The state is not an abstract creature. It is made up of people, officials, and bureaucrats.","topic":"Artificial intelligence","kind":"fact"},{"t":978,"quote":"We have the critical minerals, the energy, the talent, and the capacity to compete at every link in that value chain.","topic":"Artificial intelligence","kind":"fact"},{"t":1005,"quote":"Because artificial intelligence is not geopolitically neutral, the West must lead the development of this technology to ensure that it is consistent with our fundamental libertarian values, namely respect for life, liberty, private property, and the notion of human dignity.","topic":"Artificial intelligence","kind":"fact"},{"t":1077,"quote":"We know the cost of destroying a currency. We know the cost of turning the state into a permanent obstacle to human initiative.","topic":"Argentina economy","kind":"fact"},{"t":1085,"quote":"For a century, we tried almost every conceivable way of preventing our own greatness. And we survived.","topic":"Argentina economy","kind":"fact"},{"t":1099,"quote":"Decline is not destiny. It is the result of repeated decisions.","topic":"Argentina economy","kind":"fact"},{"t":1159,"quote":"A land that has welcomed millions who crossed oceans in the hope that their children would live better lives than they had, and who built one of the most prosperous nations on earth.","topic":"Argentina reconstruction","kind":"fact"},{"t":1194,"quote":"No nation is guaranteed a place in history. It is built generation after generation through work, through freedom, and through the determination of a people who refuse to accept that their best days are behind them.","topic":"Argentina reconstruction","kind":"fact"},{"t":1207,"quote":"We believe that Argentina still has a great story ahead of it and we have decided to go out and claim it.","topic":"Argentina reconstruction","kind":"self_credit"}],"promises":[{"t":453,"quote":"Today I have come to tell you that Argentina is not going to sit around waiting for the UN and the international community to live up to their own mandate. We're going to take matters into our own hands.","topic":"Falkland Islands","kind":"promise"},{"t":609,"quote":"which I say now will fail","topic":"UN reform","kind":"threat"},{"t":991,"quote":"A commitment not to regulate A commitment not to re regulate preemptively. limited liability for companies operating with AI agents and tax incentives.","topic":"Artificial intelligence","kind":"promise"},{"t":1056,"quote":"We will continue to participate in multilateral fora in good faith because some problems mean that we need to work together.","topic":"Artificial intelligence","kind":"promise"}],"attacks":[{"t":144,"quote":"a useless organization whose only purpose is to sustain a cast of fatally arrogant parasites masquerading as well-intentioned bureaucrats","topic":"UN reform","target":"United Nations"},{"t":172,"quote":"The alleged defenders of human rights have sheltered bloodthirsty dictatorships and regimes that stone women in the streets.","topic":"UN reform","target":"Human Rights Defenders"},{"t":239,"quote":"unilateral modifications continue. Today, the Sea Lion project is moving towards oil extraction on the Argentine continental shelf in the North Malvinus basin under British licenses that Argentina rejects as illegal and illegitimate.","topic":"Falkland Islands","target":"United Kingdom"},{"t":388,"quote":"If the United Kingdom maintains a selective interpretation of the principle of self-determination with regard to the Malinas Islands, it must also explain how it reconciles that position with the debates on self-determination taking place within its own territory.","topic":"Falkland Islands","target":"United Kingdom"},{"t":445,"quote":"We will not remain indifferent to those who exploit resources under illegal foreign occupation.","topic":"Falkland Islands","target":"Foreign Occupation Forces"},{"t":518,"quote":"condemn the attacks by the Iranian regime against the state of Israel","topic":"Iran Israel","target":"Iran"},{"t":580,"quote":"bloodthirsty bloodthirsty dictatorships and terrorist organizations coupled with Orwellian control and impositions on liberal democracies that abide by the rules","topic":"UN reform","target":"United Nations"},{"t":618,"quote":"That is how they managed the pandemic. During the pandemic, bodies under the opaces of this house put themselves before scientific evidence and the sovereignty of nations and promoted forced lockdown policies throughout the world","topic":"WHO pandemic","target":"United Nations"},{"t":642,"quote":"Where some allege a public health policy error, we see a global experiment in social control disguised as silent as science","topic":"WHO pandemic","target":"Global Health Authorities"},{"t":662,"quote":"There is a word for it, genocide","topic":"WHO pandemic","target":"Pandemic Management Policies"}],"greece":[],"said":[{"topic":"Artificial intelligence","said":0.2641,"reported":0.0,"articles":0},{"topic":"Falkland Islands","said":0.2089,"reported":0.0,"articles":0},{"topic":"UN reform","said":0.1803,"reported":0.0,"articles":0},{"topic":"Argentina economy","said":0.1023,"reported":0.0,"articles":0},{"topic":"Argentina reconstruction","said":0.0853,"reported":0.0,"articles":0},{"topic":"Iran Israel","said":0.0542,"reported":1.0,"articles":1},{"topic":"Industrial revolution","said":0.0535,"reported":0.0,"articles":0},{"topic":"WHO pandemic","said":0.0515,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Proto Thema","date":"2026-09-23","title":"Ο Μιλέι χορεύει με μαθητές εβραϊκού σχολείου στη Νέα Υόρκη, όπου βραβεύτηκε για την υποστήριξή του στο Ισραήλ, δείτε βίντεο","url":"https://www.protothema.gr/world/article/1883167/o-milei-horeuei-me-mathites-evraikou-sholeiou-sti-nea-uorki-opou-vraveutike-gia-tin-upostirixi-tou-sto-israil","tone":"neutral"}],"transcript":[{"t":3,"topic":"Argentina economy","text":"The assembly will now hear an address by His Excellency Javier Herado Mille, President of the Argentine Republic. I request protocol to escort his and invite him to address the assembly. Mr. President, heads of state, representatives of the peoples of the Today I address you for the third time as president of all Argentines. When we took office of a country in ruins, on the brink of the worst crisis in its history, one thing was clear to us from the outset. We had to confront our problems with absolute honesty."},{"t":65,"topic":"UN reform","text":"Lying to ourselves in order to feel better was going to get us nowhere. It's always preferable to take an tell an uncomfortable truth than a comforting So believe me when I say that I know what I'm talking about when in a constructive spirit I point to the problems facing this organization which purports to guide states and arbitrate between them. In that regard, I want to talk about three issues today. First, what this body should have done and failed to do. Second, what it should not have done but did anyway. And third, its position in the face of the advent of artificial intelligence. 78 years ago, this house declared that all human beings are born free and equal in dignity and rights. Noble words whose spirit I fully share. To that end, it undertook to uphold international law, defend the sovereignty of nations, and provide a forum in which conflicts could be resolved through cooperation rather than immediately through the force of arms."},{"t":130,"topic":"UN reform","text":"That was the original purpose, the contract that we all signed. But today, regrettably, it is time to acknowledge that in practice, that sacred covenant has been broken. That's to say, it's become a useless organization whose only purpose is to sustain a cast of fatally arrogant parasites masquerading as well-intentioned bureaucrats. I would remind them of what Mises said. Good people do not think about controlling the lives of their fellow human beings. Those who were supposed to guarantee collective security and human rights failed in their task. Instead, they allowed chaos, violence, and international terrorism to flourish. The alleged defenders of human rights have sheltered bloodthirsty dictatorships and regimes that stone women in the streets. They have systematically voted against Israel while remaining silent in the face of Islamic terrorism and the genocide of Christians in Africa. And as if that were not enough, an organization established to defend the territorial sovereignty of its members decided to look the other way with regard to the situation of the Malvvenas Islands, South Georgia Islands at South Sandwich Islands and the surrounding maritime For us, the Malinas are a national cause."},{"t":209,"topic":"Falkland Islands","text":"I repeat, the Malvinas for us are a national cause. They are also a test of the gulf that can exist between the words of intent international institutions and the reality upon which they purport to act. 50 years ago, this very assembly adopted resolution 3149 which calls on parties to refrain from introducing unilateral modifications while the dispute remains unresolved. 50 years on, the situation has not changed. Yet, unilateral modifications continue. Today, the Sea Lion project is moving towards oil extraction on the Argentine continental shelf in the North Malvinus basin under British licenses that Argentina rejects as illegal and illegitimate. Any such activity not authorized by the Argentine Republic in this regard constitutes an unlawful act under both international law including the UN Convention on the Law of the Sea and Argentine domestic law."},{"t":272,"topic":"Falkland Islands","text":"That is why I wish to ask a question. What use is a resolution if for decades the other party can act in direct contravention of it while that resolution remains intact in the archives but powerless in the face of reality. There's no shortage of words or resolutions. What is lacking is consequences. Because an institution that cannot ensure that its words carry weight in the real world loses the most important thing of all, its authority. In these circumstances, those who follow the rules receive no reward for doing so, while those who break them suffer no re repercussions whatsoever. That's why the malvenas are not merely an issue between Argentina and the United Kingdom. They also raise a question regarding the ability of this organization to enforce its own Argentina has taken note of that reality and in the face of the unauthorized exploitation of our resources in the disputed area, we've acted. We've submitted formal notes of protest."},{"t":334,"topic":"Falkland Islands","text":"We've availed ourselves of the legal remedies at our disposal. We've imposed sanctions on the companies involved and their suppliers. And we've submitted a national sovereignty defense bill to Congress. For far too long, Argentine governments opted for a rhetorical defense. We have chosen a peaceful, practical, and effective defense. I repeat, we have chosen a peaceful, practical, and effective defense. I also wish to reiterate our position regarding the population of the islands. As this very assembly is determined in numerous resolutions, the principle of self-determination does not apply in this case since the population was implanted by the occupying power on a territory whose sovereignty is in dispute. That principles ex principle exists to liberate colonized people, not to legitimize situations arising from colonization. If the United Kingdom maintains a selective interpretation of the principle of self-determination with regard to the Malinas Islands, it must also explain how it reconciles that position with the debates on self-determination taking place within its own territory."},{"t":404,"topic":"Falkland Islands","text":"Once again, we call on the United Kingdom to resume negotiations with a view to finding a peaceful solution to the sovereignty dispute as required by international law. We also reiterate our invitation to proceed without delay to an exchange of views with a view to resolving the issue concerning the affforementioned dispute over the exploitation of our natural resources. And I want to say something more to the global energy sector. Vakam Muerta represents a h historic opportunity with the potential to become one of the major players in the energy sector in the decades ahead. Come invest develop develop it with us. But there's a limit to this invitation. We will not remain indifferent to those who exploit resources under illegal foreign occupation. Argentina Argentina's position is clear. Today I have come to tell you that Argentina is not going to sit around waiting for the UN and the international community to live up to their own mandate. We're going to take matters into our own hands. For far too long, Argentina managed its own decline."},{"t":467,"topic":"Iran Israel","text":"We managed poverty. We managed isolation. We managed irrelevance. We grew accustomed to debating how to divide up what remained rather than asking ourselves how we could grow again, how we could rebuild what we had lost. That's over. We've already lost too much. We do not want to lose it again. That's why we've embraced free enterprise capitalism. We're opening our economy up to trade and investment. We are advancing in the development of our strategic resources. We've embraced the technological revolution and we are rebuilding our military capabilities after decades of neglect. We've also made a geopolitical choice. We have unequivocally aligned ourselves with the West, with the United States, and with Israel, countries with which we share a deep affinity of values and strategic complimentarity. That is why we condemn the attacks by the Iranian regime against the state of Israel. We have designated the Iranian Revolutionary Guard as a terrorist organization and continue to seek justice for the two terrorist attacks perpetrated on Argentine soil in 1992 and 1994."},{"t":535,"topic":"UN reform","text":"We have decided to cooperate with the world, but to do so standing tall in the understanding that only a nation that is politically relevant, economically influential, and militarily respected can truly be a master of its own Mr. President, just as I have shown you how the UN failed to do what it was supposed to do, now I want to tell you how it has excelled at what no one asked it to do and what it should never have been doing. Because alongside that failure, they have built a bureaucratic leviathan devoted to deciding how the peoples of the world and their citizens should live. This amounts to a curious mixture of anarchy and tyranny, impotence in the face of those who break the most basic rules such as bloodthirsty bloodthirsty dictatorships and terrorist organizations coupled with Orwellian control and impositions on liberal democracies that abide by the rules. We saw this with the millennium agenda. We saw it with the 2030 agenda with economic regulation, gender agendas, environmental extremism, and unchecked And every time they failed, rather than reviewing the model or apologizing, they doubled down, as they are already doing with the 2045 agenda, which I say now will fail."},{"t":612,"topic":"WHO pandemic","text":"But perhaps the most serious example, the one that forever should shame this organization, is quite another. That is how they managed the pandemic. During the pandemic, bodies under the opaces of this house put themselves before scientific evidence and the sovereignty of nations and promoted forced lockdown policies throughout the world that ruined jobs that ruined the education of entire generation of children and cost the lives of millions of people who died alone without basic medical care. Where some allege a public health policy error, we see a global experiment in social control disguised as silent as science. And when a state wearing public health blinkers deprivives its population of the right to work, to receive an education, and to bid farewell to their dead, this results in millions of unavoidable deaths. There is a word for it, genocide. That happens in many countries including Argentina which boasted of being the World Health Organization's star pupil and that is why we decided to leave the World Health Organization."},{"t":676,"topic":"Artificial intelligence","text":"Added to that is something more subtle but equally damaging. The psychological terror instilled by the state. For years, citizens around the world were told that they should be afraid. Afraid of their neighbors, of the air they breathe, of leaving their homes. That fear wasn't a mere side effect. It was the chosen instrument of their government. The problem is that emergencies eventually pass. Fear passes. Generations move on. But the institutions and powers created on the pretext of those alleged emergencies remain. And if for a moment we allow ourselves to believe that the lesson had been learned after so many failures, the arrival of artificial intelligence demonstrates quite something else. The printing press, the steam engine, electricity, the internet, every great technological revolution has been accompanied by fears about what it would destroy, particularly jobs. There is no doubt that this is one of the most effective ways of instilling fear in human beings given the role of work as a means of subsistence."},{"t":737,"topic":"Industrial revolution","text":"Take the industrial revolution as an example. When it began, the world was home to some 800 million human beings. If in keeping with the lites and the perennial pessimists employment had at best remained constant then given that the world's population has since increased more than 10fold the global employment rate today would be at That is absurd. something that few of us few seem to have stopped to consider perhaps except perhaps those of us with a passion for reading Bourhees who love his approach for testing an idea by taking it to its logical extreme. Ultimately these technological advances have not only failed to produce any of the catastrophes but in addition all of these ended up bringing an end to what human beings were able to do. Today we have built machines that are able to carry out tasks that only a few months ago seemed uh out of our reach."},{"t":803,"topic":"Artificial intelligence","text":"Where we many see a threat, we see a new frontier. Artificial intelligence or super intelligence as Donald Trump said can double our productivity uh in a way that we do not yet comprehend. to invoke Adam Smith. Artificial intelligence will be the pin factory of the 21st century and much more besides. It can transform our economies, our medicine, our education, even the way we govern. That calls for prudence, yes, but prudence doesn't mean fear. Moreover, under no circumstances should fear automatically translate into obedience. Indeed, the dystopian scenarios commonly invoked to instill fear and justify state control make no sense from an economic standpoint. The answer lies with Adam Smith. Artificial intelligence, like the division of labor, in the case of the pin factory, is an accelerator of productivity growth. Smith noted, however, that the division of labor is limited by the extent of the Growth will therefore be constrained by its counterpart in genuine demand without fiscal deficits or speurious money creation."},{"t":878,"topic":"Artificial intelligence","text":"But that's not all. Those projects must also be financed and that should be done with the resources of human beings. That is their initial endowments and level of wealth which correspond to the side of the market. Moreover, the purpose of producing more is to achieve a higher level of consumption. Yet the satisfaction generated by consumption increases at a decreasing rate while the loss of satisfaction involved in surrendering leisure in order to produce more rises disproportionately. Consequently, the point at which the gain from greater consumption is equal to the loss of leisure brings the system to an equilibrium leaving no room for dystopian terror. That is why when we hear that the state should control artificial intelligence, we should remember something basic. The state is not an abstract creature. It is made up of people, officials, and bureaucrats. Granting it control over innovation means granting some people, in the best and most naive of cases, the power to limit what everyone else can create."},{"t":941,"topic":"Artificial intelligence","text":"History gives us reason to scrutinize such power carefully. For centuries, fear over tomorrow has been used as an argument for restricting freedoms today. Always with the same promise. Give us a part of your freedom and we will protect you from this new threat. We will apply a different principle. In the face of uncertainty, we propose determination. In the face of fear, courage, in the face of decline, ambition, and in the face of resignation, we propose optimism. That is why I tell you that when it comes to artificial intelligence, Argentina will stand at the forefront of freedom. We have the critical minerals, the energy, the talent, and the capacity to compete at every link in that value chain. And we want to become the most competitive place in the world in which to develop it with a cutting edge legal framework. A commitment not to regulate A commitment not to re regulate preemptively. limited liability for companies operating with AI agents and tax incentives."},{"t":1005,"topic":"Artificial intelligence","text":"Because artificial intelligence is not geopolitically neutral, the West must lead the development of this technology to ensure that it is consistent with our fundamental libertarian values, namely respect for life, liberty, private property, and the notion of human dignity. In that regard, we fully share President Trump's vision. Mr. President, we are living through one of those strange moments in history when one world begins to disappear before the next has finished being born. These are dangerous times, but they are also extraordinary times because during long periods of stability, nations manage the world they have inherited. During periods of transformation, some have the opportunity to build the world that is to come. Argentina wants to be one of them. We will continue to participate in multilateral fora in good faith because some problems mean that we need to work together. But we mustn't confuse cooperation with subordination."},{"t":1068,"topic":"Argentina economy","text":"We believe in alliances and above all in nations. Argentina speaks from the experience of a country that knows its own mistakes. We know the cost of isolation. We know the cost of destroying a currency. We know the cost of turning the state into a permanent obstacle to human initiative. For a century, we tried almost every conceivable way of preventing our own greatness. And we survived. Not unscathed, but we survived. Perhaps that is why today we understand something that other nations may forget. Decline is not destiny. It is the result of repeated decisions. And if a course can be chosen, it can also be changed. And that is what Argentina is trying to do. We have the energy that the world will need. We have food. We have critical minerals. We have human talent. We have the South Atlantic. And we are a natural gateway to Antarctica. And we have something that for far too long we lacked. The will to transform our potential into national power. We want an Argentina that is prosperous, influential, and powerful."},{"t":1133,"topic":"Argentina reconstruction","text":"Not to subjugate others, but to be free. Not to not to conquer others, but so that our destiny may be decided by Argentines themselves. That is why I say to the free men and women of the world, to scientists, entrepreneurs and create and creators, to those who have dreamed of a land where they can make a new beginning, look south. There you will find a vast land of fertile fields, oil, minerals, and human talent. A land that has welcomed millions who crossed oceans in the hope that their children would live better lives than they had, and who built one of the most prosperous nations on earth. We have a responsibility to live up to that legacy. We do not know exactly what the world now being born will look like. But we do know what kind of nation we want to be when it arrives. A free nation, a prosperous nation, a sovereign one, a nation capable of defending what is its own and open to the world. A nation unafraid once again to utter a word that for far too long seemed forbidden. Greatness."},{"t":1194,"topic":"Argentina reconstruction","text":"No nation is guaranteed a place in history. It is built generation after generation through work, through freedom, and through the determination of a people who refuse to accept that their best days are behind them. We believe that Argentina still has a great story ahead of it and we have decided to go out and claim it. May God bless all peoples of the world. May God bless the Argentine Republic. May the forces of heaven be with us and long live freedom. Damn it. On behalf of the assembly, I wish to thank the president of the Argentine"}],"compare":[{"topic":"Artificial Intelligence","share":0.2641,"mean":0.0494,"rank":5,"others":83},{"topic":"Falkland Islands","share":0.2089,"mean":0.0,"rank":1,"others":0},{"topic":"UN & its reform","share":0.1803,"mean":0.2049,"rank":104,"others":170},{"topic":"Middle East","share":0.0542,"mean":0.0071,"rank":14,"others":19},{"topic":"Industrial Revolution","share":0.0535,"mean":0.0,"rank":1,"others":0},{"topic":"Global Health","share":0.0515,"mean":0.0022,"rank":5,"others":6}]};
